import { BigNumbersSectionData } from '../types';

const MONTHLY_CARD_PERIOD_TYPES = ['YTD', 'R3M', 'MTH'] as const;
const QUARTER_CARD_PERIOD_TYPES = ['Q1', 'Q2', 'Q3', 'Q4'] as const;
const HALF_CARD_PERIOD_TYPES = ['H1', 'H2'] as const;

const matchesQuarterCard = (
  cardPeriodType: string | undefined,
  activeCardPeriodType: string,
): boolean => {
  const normalizedCardType = cardPeriodType?.toUpperCase();

  return (
    normalizedCardType === activeCardPeriodType || normalizedCardType === 'QTR'
  );
};

const matchesHalfCard = (
  cardPeriodType: string | undefined,
  activeCardPeriodType: string,
): boolean => {
  const normalizedCardType = cardPeriodType?.toUpperCase();

  return (
    normalizedCardType === activeCardPeriodType || normalizedCardType === 'HALF'
  );
};

const getFallbackCardIndex = (activeCardPeriodType: string): number => {
  const monthlyIndex = MONTHLY_CARD_PERIOD_TYPES.indexOf(
    activeCardPeriodType as (typeof MONTHLY_CARD_PERIOD_TYPES)[number],
  );

  if (monthlyIndex >= 0) {
    return monthlyIndex;
  }

  if (
    QUARTER_CARD_PERIOD_TYPES.includes(
      activeCardPeriodType as (typeof QUARTER_CARD_PERIOD_TYPES)[number],
    ) ||
    HALF_CARD_PERIOD_TYPES.includes(
      activeCardPeriodType as (typeof HALF_CARD_PERIOD_TYPES)[number],
    )
  ) {
    return 1;
  }

  return 0;
};

export function getVolumeBigNumbersSelectedCardIndex(
  cards: BigNumbersSectionData[] | undefined,
  activeCardPeriodType: string | null,
): number {
  if (!activeCardPeriodType) {
    return 0;
  }

  const normalizedActive = activeCardPeriodType.toUpperCase();

  if (cards?.length) {
    const directIndex = cards.findIndex(
      (card) => card.period_type?.toUpperCase() === normalizedActive,
    );

    if (directIndex >= 0) {
      return directIndex;
    }

    if (
      QUARTER_CARD_PERIOD_TYPES.includes(
        normalizedActive as (typeof QUARTER_CARD_PERIOD_TYPES)[number],
      )
    ) {
      const quarterIndex = cards.findIndex((card) =>
        matchesQuarterCard(card.period_type, normalizedActive),
      );

      if (quarterIndex >= 0) {
        return quarterIndex;
      }
    }

    if (
      HALF_CARD_PERIOD_TYPES.includes(
        normalizedActive as (typeof HALF_CARD_PERIOD_TYPES)[number],
      )
    ) {
      const halfIndex = cards.findIndex((card) =>
        matchesHalfCard(card.period_type, normalizedActive),
      );

      if (halfIndex >= 0) {
        return halfIndex;
      }
    }
  }

  return getFallbackCardIndex(normalizedActive);
}
